const state = $getWorkflowStaticData('global');
const users = state.users ?? {};

// Eintreffendes Item (mit dem binären Bild, falls vorhanden).
const item = $input.first();
const binary = item.binary ?? {};
const image = binary.image ?? Object.values(binary)[0];

// Ohne Bild-Daten (z. B. include_image = false) wird gar nichts
// gesendet - nie eine reine Textnachricht.
if (!image) return [];

const time = new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC';
const text = `🐰 Hase entdeckt – ${time}`;

// Ausgabe: ein Item pro Benutzer mit aktiven Bildern.
// Benutzer mit ausgeschalteten Bildern werden nicht kontaktiert.
const recipients = Object.entries(users)
  .filter(([, user]) => user.images === true)
  .map(([key]) => ({
    chatId: key.replace(/^user-/, ''),
    text,
    binary: { image },
  }));

return recipients;

const state = $getWorkflowStaticData('global');
if (!state.users) state.users = {};

const input = $input.first().json;
const message = input.message ?? {};
const chatId = String(message.chat?.id ?? '');
const text = String(message.text ?? '').trim();
const command = (text.split(/\s+/)[0] ?? '').toLowerCase().split('@')[0];

if (!chatId) return [];

// Optional: nur diese Telegram-IDs dürfen die restlichen Befehle nutzen.
// Leere Liste = jeder Benutzer darf seine eigene Bild-Einstellung verwalten.
const ALLOWED = []; // z. B. ['632078830', '123456789']

// /chat-id funktioniert für jeden, auch ohne Freischaltung.
if (command === '/chat-id') {
  return [{ json: { chatId, text: chatId } }];
}

if (ALLOWED.length && !ALLOWED.includes(chatId)) {
  return [{ json: { chatId, text: 'Deine Telegram-ID ist nicht freigeschaltet.' } }];
}

// Pro-Benutzer-Einstellung beim ersten Kontakt anlegen.
// Default: Bilder an.
const key = `user-${chatId}`;
if (!state.users[key]) {
  state.users[key] = { images: true };
}
const user = state.users[key];

// z. B. an den Bot gesendete Fotos: ohne Text ignorieren
if (command === '') return [];

const help = [
  'Befehle:',
  '/start – ich möchte Bilder, wenn ein Hase entdeckt wird',
  '/stop – ich möchte nichts bekommen',
  '/status – aktuelle Einstellung anzeigen',
  '/chat-id – meine Chat-ID anzeigen',
].join('\n');

switch (command) {
  case '/start':
    user.images = true;
    return [{ json: { chatId, text: '📷 Ich schicke dir Bilder, wenn ein Hase entdeckt wird.' } }];
  case '/stop':
    user.images = false;
    return [{ json: { chatId, text: '⏸ Ich schicke dir nichts mehr.' } }];
  case '/status':
    return [{ json: { chatId, text: user.images
      ? '📷 Bilder an: Ich schicke dir Bilder, wenn ein Hase entdeckt wird.'
      : '⏸ Bilder aus: Ich schicke dir nichts.' } }];
  case '/hilfe':
  case '/help':
    return [{ json: { chatId, text: help } }];
  default:
    return [{ json: { chatId, text: 'Unbekannter Befehl. /hilfe für die Übersicht.' } }];
}
